// frontend/src/user/utils/reverseGeocode.js
// ============================================================
//  Reverse Geocoding — آدرس دقیق برای ایران با Nominatim
//
//  ⚠️ اصول کار (بر اساس پروژه Mission Market):
//     1. zoom=18 (سطح ساختمان) — کامل‌ترین اطلاعات
//     2. از آبجکت address همه فیلدهای مرتبط رو بردار
//     3. ترتیب منطقی ایران: شهر → محله → خیابان + پلاک
//     4. اگر فیلدی خالی بود، از fallback استفاده کن
// ============================================================

export async function reverseGeocode(lat, lng, opts = {}) {
  const url =
    `https://nominatim.openstreetmap.org/reverse` +
    `?format=json&lat=${lat}&lon=${lng}` +
    `&accept-language=fa&zoom=18&addressdetails=1`;

  const res = await fetch(url, {
    headers: { Accept: 'application/json' },
  });

  if (!res.ok) throw new Error('خطا در دریافت آدرس');

  const data = await res.json();
  if (!data) return '';

  const a = data.address || {};

  // ─── helper: اولین مقدار non-empty رو برگردون ───
  const pick = (...vals) => {
    for (const v of vals) {
      const s = String(v || '').trim();
      if (s) return s;
    }
    return '';
  };

  // ─── helper: پیشوندها رو حذف کن (شهر ، شهرستان ، استان ، بخش) ───
  const strip = (s, ...prefixes) => {
    let r = String(s || '').trim();
    for (const p of prefixes) {
      if (r.startsWith(p)) r = r.slice(p.length).trim();
    }
    return r;
  };

  // ═══ استخراج تمام فیلدهای ممکن ═══
  const city = strip(
    pick(a.city, a.town, a.village, a.municipality),
    'شهر ',
    'شهرستان '
  );

  const cityDistrict = pick(a.city_district, a.district); // مثال: منطقه ۱

  // محله / محوطه بزرگتر (احتمالاً اسم بلوار/منطقه)
  const suburb = pick(
    a.suburb,
    a.quarter,
    a.neighbourhood,
    a.hamlet,
    a.residential
  );

  // خیابان اصلی (احتمالاً اسم خیابان یا کوچه)
  const road = pick(
    a.road,
    a.pedestrian,
    a.footway,
    a.path,
    a.boulevard,
    a.avenue
  );

  const houseNumber = pick(a.house_number);

  // ─── حالت فقط شهر (برای محدوده) ───
  if (opts.cityOnly) {
    return city || suburb || '';
  }

  // ═══ ساخت آدرس نهایی ═══
  // ترتیب ایران: شهر → محله → خیابان+پلاک
  const parts = [];
  const seen = new Set();

  const push = (v) => {
    const s = String(v || '').trim();
    if (s && !seen.has(s)) {
      seen.add(s);
      parts.push(s);
    }
  };

  push(city);
  push(cityDistrict);      // مثلاً "منطقه ۱" — اگه خالی باشه بی‌اثره
  push(suburb);            // محله یا نام منطقه بزرگ‌تر (ممکنه اسم بلوار داشته باشه)

  if (road) {
    let street = road;
    if (houseNumber && !street.includes(houseNumber)) {
      street = `${road} ${houseNumber}`;
    }
    push(street);
  }

  let result = parts.join('، ');

  // ═══ اگر همه فیلدها خالی بود → از display_name تمیز کن ═══
  if (!result) {
    result = cleanDisplayName(data.display_name || '');
  }

  // ═══ محدودیت نهایی طول ═══
  if (result.length > 150) {
    result = result.substring(0, 150) + '...';
  }

  return result;
}

// ============================================================
//  تمیزکاری display_name (fallback)
// ============================================================
function cleanDisplayName(name) {
  if (!name) return '';
  let s = String(name);

  s = s.replace(/،?\s*ایران\s*$/i, '');           // حذف کشور
  s = s.replace(/،?\s*\d{5}[-–]?\d{5}\s*/g, '');   // حذف کدپستی
  s = s.replace(/،?\s*بخش\s+[^،,]+/g, '');         // حذف بخش
  s = s.replace(/،?\s*شهرستان\s+[^،,]+/g, '');     // حذف شهرستان
  s = s.replace(/،?\s*استان\s+[^،,]+/g, '');       // حذف استان

  s = s.replace(/^[،,\s]+|[،,\s]+$/g, '');         // کاماهای لبه
  s = s.replace(/[،,]\s*[،,]+/g, '، ');            // کاماهای تکراری

  return s.trim();
}

export default reverseGeocode;