const MARKER_ICON_VALID = buildMarkerIcon(VALID_COLOR, false);
const MARKER_ICON_INVALID = buildMarkerIcon(INVALID_COLOR, false);
const MARKER_ICON_ACTIVE = buildMarkerIcon(BRAND_COLOR, true);

// ============================================================
//  📐 Haversine distance (km)
// ============================================================
function haversineKm(lat1, lng1, lat2, lng2) {
  const R = 6371;
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// ============================================================
//  📝 Address combine/parse
// ============================================================
const PLAQUE_MARK = '، پلاک ';
const UNIT_MARK = '، واحد ';

function combineAddress(base, plaque, unit) {
  let out = (base || '').trim();
  const p = (plaque || '').trim();
  const u = (unit || '').trim();
  if (p) out += `${PLAQUE_MARK}${p}`;
  if (u) out += `${UNIT_MARK}${u}`;
  return out;
}

function parseFullAddress(full) {
  if (!full) return { base: '', plaque: '', unit: '' };
  let addr = String(full);
  let unit = '';
  let plaque = '';

  const idxUnit = addr.lastIndexOf(UNIT_MARK);
  if (idxUnit !== -1) {
    unit = addr.slice(idxUnit + UNIT_MARK.length).trim();
    addr = addr.slice(0, idxUnit).trim();
  }

  const idxPlaque = addr.lastIndexOf(PLAQUE_MARK);
  if (idxPlaque !== -1) {
    plaque = addr.slice(idxPlaque + PLAQUE_MARK.length).trim();
    addr = addr.slice(0, idxPlaque).trim();
  }

  return { base: addr, plaque, unit };
}

// ============================================================
//  🔍 مقایسه دو آبجکت delivery
// ============================================================
function isSameDelivery(a, b) {
  if (!a || !b) return a === b;
  return (
    (a.city || '') === (b.city || '') &&
    (a.address || '') === (b.address || '') &&
    (a.lat ?? null) === (b.lat ?? null) &&
    (a.lng ?? null) === (b.lng ?? null)
  );
}

// ============================================================
//  🗺️ Map helpers
// ============================================================
function MapClickHandler({ onMapClick, disabled }) {
  useMapEvents({
    click(e) {
      if (!disabled) onMapClick(e.latlng.lat, e.latlng.lng);
    },
  });
  return null;
}

function MapRefSetter({ mapRef }) {
  const map = useMap();
  useEffect(() => {
    mapRef.current = map;
  }, [map, mapRef]);
  return null;
}

function MapResizer() {
  const map = useMap();
  useEffect(() => {
    const t = setTimeout(() => map.invalidateSize(), 250);
    return () => clearTimeout(t);
  }, [map]);
  return null;
}

// ============================================================
//  🏙️ Hook: Delivery cities
//  ✅ FIX: استفاده از publicAxios با baseURL (بدون hardcode)
// ============================================================
function useDeliveryCities() {
  const [cities, setCities] = useState([]);
  const [loadingCities, setLoadingCities] = useState(true);
  const [citiesError, setCitiesError] = useState('');
  const isMountedRef = useRef(true);

  const loadCities = useCallback(() => {
    setLoadingCities(true);
    setCitiesError('');

    publicAxios
      .get('/api/delivery-cities')
      .then((res) => {
        if (!isMountedRef.current) return;
        const list = Array.isArray(res.data?.cities) ? res.data.cities : [];
        setCities(list);
      })
      .catch((err) => {
        if (!isMountedRef.current) return;
        logDebug('delivery-cities error:', err);
        setCitiesError(
          'خطا در دریافت لیست شهرها — لطفاً اتصال اینترنت را بررسی کنید.'
        );
      })
      .finally(() => {
        if (isMountedRef.current) setLoadingCities(false);
      });
  }, []);

  useEffect(() => {
    isMountedRef.current = true;
    loadCities();
    return () => {
      isMountedRef.current = false;
    };
  }, [loadCities]);

  return {
    cities,
    loadingCities,
    citiesError,
    retryCities: loadCities,
  };
}

// ============================================================
//  🔢 StepBadge
// ============================================================
function StepBadge({ num, active = false }) {
  return (
    <span
      className={`flex-shrink-0 w-6 h-6 rounded-2xl flex items-center justify-center text-[10px] font-black font-num ${
        active
          ? 'bg-brand-gradient text-white shadow-brand'
          : 'bg-paper-100 dark:bg-ink-700 text-ink-600 dark:text-cream-300'
      }`}
      aria-hidden="true"
    >
      {num}
    </span>
  );
}

// ============================================================
//  💾 SavedAddressesList
// ============================================================
function SavedAddressesList({ onSelect, disabled }) {
  const [saved, setSaved] = useState([]);

  useEffect(() => {
    setSaved(loadSavedAddresses());
  }, []);

  if (saved.length === 0) return null;

  const handleRemove = (idx, e) => {
    e.stopPropagation();
    try {
      const next = saved.filter((_, i) => i !== idx);
      localStorage.setItem(SAVED_ADDRESSES_KEY, JSON.stringify(next));
      setSaved(next);
    } catch {
      /* silent */
    }
  };

  return (
    <div className="mb-3">
      <div className="text-[10px] font-black text-ink-500 dark:text-cream-400 mb-2 flex items-center gap-1.5">
        <SiteImage
          imageKey="icon_save"
          fallback="💾"
          alt=""
          className="w-3.5 h-3.5 object-contain"
        />
        <span>آدرس‌های ذخیره‌شده (برای استفاده سریع):</span>
      </div>
      <div className="space-y-1.5 max-h-40 overflow-y-auto scrollbar-hide">
        {saved.map((addr, idx) => (
          <div
            key={idx}
            className="w-full flex items-stretch gap-1 p-1 bg-paper-100 dark:bg-ink-900/50 border-2 border-ink-200 dark:border-dark-600 rounded-2xl hover:border-brand-300 dark:hover:border-brand-500/40 hover:bg-brand-50/60 dark:hover:bg-brand-500/10 transition group"
          >
            <button
              type="button"
              onClick={() => !disabled && onSelect(addr)}
              disabled={disabled}
              className="flex-1 min-w-0 text-right flex items-start gap-2.5 p-2 rounded-xl active:bg-brand-50 dark:active:bg-brand-500/15 transition touch-target disabled:opacity-60"
            >
              <SiteImage
                imageKey="icon_location"
                fallback="📍"
                alt=""
                className="w-4 h-4 object-contain flex-shrink-0 mt-0.5"
              />
              <div className="flex-1 min-w-0">
                <div className="text-[11px] font-black text-ink-800 dark:text-cream-100 truncate">
                  {addr.city}
                </div>
                <div className="text-[10px] text-ink-500 dark:text-cream-400 truncate mt-0.5">
                  {addr.address}
                </div>
              </div>
            </button>
            <button
              type="button"
              onClick={(e) => handleRemove(idx, e)}
              className="flex-shrink-0 w-8 flex items-center justify-center text-ink-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-500/15 active:bg-rose-100 rounded-xl transition text-xs touch-target"
              title="حذف از لیست"
              aria-label={`حذف آدرس ${addr.city} از لیست`}
            >
              ✕
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

// ============================================================
//  🎯 کامپوننت اصلی
// ============================================================
export default function DeliveryLocationPicker({ value, onChange, disabled = false }) {
  const { cities, loadingCities, citiesError, retryCities } = useDeliveryCities();

  const [selectedCityName, setSelectedCityName] = useState(value?.city || '');
  const [position, setPosition] = useState(
    value?.lat != null && value?.lng != null
      ? { lat: Number(value.lat), lng: Number(value.lng) }
      : null
  );

  const [address, setAddress] = useState('');
  const [plaque, setPlaque] = useState('');
  const [unit, setUnit] = useState('');

  const [locating, setLocating] = useState(false);
  const [locationError, setLocationError] = useState('');
  const [confirmed, setConfirmed] = useState(
    !!(value?.city && value?.lat != null && value?.lng != null && value?.address)
  );

  const [fetchingAddress, setFetchingAddress] = useState(false);
  const [addressFetchError, setAddressFetchError] = useState('');
  const [showPlaqueUnit, setShowPlaqueUnit] = useState(
    !!(
      value?.address &&
      (value.address.includes(PLAQUE_MARK) || value.address.includes(UNIT_MARK))
    )
  );

  const addressEditedRef = useRef(false);
  const mapRef = useRef(null);
  const initialRecenterRef = useRef(false);
  const isMountedRef = useRef(true);

  const onChangeRef = useRef(onChange);
  useEffect(() => {
    onChangeRef.current = onChange;
  }, [onChange]);

  const lastEmittedRef = useRef(null);
  const lastExternalValueRef = useRef(null);
  const positionSourceRef = useRef('initial');

  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  // ============================================================
  //  📢 emitChange
  // ============================================================
  const emitChange = useCallback((next) => {
    if (!onChangeRef.current) return;
    if (isSameDelivery(lastEmittedRef.current, next)) return;
    lastEmittedRef.current = next;
    lastExternalValueRef.current = next;
    onChangeRef.current(next);
  }, []);

  // ============================================================
  //  🔄 Init از value
  // ============================================================
  useEffect(() => {
    const initial = parseFullAddress(value?.address || '');
    setAddress(initial.base);
    setPlaque(initial.plaque);
    setUnit(initial.unit);
    if (value?.address && value.address.trim().length > 0) {
      addressEditedRef.current = true;
    }
    lastExternalValueRef.current = {
      city: value?.city || '',
      address: value?.address || '',
      lat: value?.lat ?? null,
      lng: value?.lng ?? null,
    };
    lastEmittedRef.current = lastExternalValueRef.current;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ============================================================
  //  ✅ Validate city در برابر لیست سرور
  // ============================================================
  useEffect(() => {
    if (!cities.length || !value?.city) return;
    const found = cities.some((c) => c.name === value.city);
    if (!found) {
      setSelectedCityName('');
      setPosition(null);
      setConfirmed(false);
    }
  }, [cities, value?.city]);

  const showMap = !!selectedCityName;

  const flyTo = useCallback((lat, lng, zoom = 15, duration = 0.8) => {
    if (!mapRef.current) return;
    mapRef.current.flyTo([lat, lng], zoom, { duration });
  }, []);

  // ============================================================
  //  🎯 Recenter در mount اول
  // ============================================================
  useEffect(() => {
    if (!initialRecenterRef.current && position && mapRef.current && showMap) {
      initialRecenterRef.current = true;
      setTimeout(() => {
        flyTo(position.lat, position.lng, 16, 0);
      }, 300);
    }
  }, [position, showMap, flyTo]);

  // ============================================================
  //  🔄 Sync با value خارجی
  // ============================================================
  useEffect(() => {
    if (!value) return;
    if (isSameDelivery(lastExternalValueRef.current, value)) return;

    lastExternalValueRef.current = {
      city: value?.city || '',
      address: value?.address || '',
      lat: value?.lat ?? null,
      lng: value?.lng ?? null,
    };
    lastEmittedRef.current = lastExternalValueRef.current;

    if (value.city !== selectedCityName) {
      setSelectedCityName(value.city || '');
    }

    if (
      value.lat != null &&
      value.lng != null &&
      (position?.lat !== Number(value.lat) || position?.lng !== Number(value.lng))
    ) {
      setPosition({ lat: Number(value.lat), lng: Number(value.lng) });
    }

    if (value.address !== undefined) {
      const parsed = parseFullAddress(value.address);
      const currentCombined = combineAddress(address, plaque, unit);
      if (value.address !== currentCombined) {
        setAddress(parsed.base);
        setPlaque(parsed.plaque);
        setUnit(parsed.unit);
        if (value.address) addressEditedRef.current = true;
        if (parsed.plaque || parsed.unit) setShowPlaqueUnit(true);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value?.city, value?.lat, value?.lng, value?.address]);

  // ============================================================
  //  🏙️ شهر انتخاب‌شده + اعتبارسنجی
  // ============================================================
  const selectedCity = useMemo(
    () => cities.find((c) => c.name === selectedCityName) || null,
    [cities, selectedCityName]
  );

  const distanceKm = useMemo(() => {
    if (!selectedCity || !position) return null;
    return haversineKm(
      position.lat,
      position.lng,
      Number(selectedCity.lat),
      Number(selectedCity.lng)
    );
  }, [selectedCity, position]);

  const isInside = useMemo(() => {
    if (distanceKm == null || !selectedCity) return false;
    return distanceKm <= Number(selectedCity.radius_km || 0);
  }, [distanceKm, selectedCity]);

  const radiusKm = selectedCity ? Number(selectedCity.radius_km || 0) : 0;

  // ============================================================
  //  🌍 Reverse Geocoding خودکار
  // ============================================================
  useEffect(() => {
    if (!position || disabled) return;
    if (addressEditedRef.current) return;
    if (positionSourceRef.current === 'city') return;

    let cancelled = false;

    const timer = setTimeout(async () => {
      if (cancelled || !isMountedRef.current) return;
      setFetchingAddress(true);
      setAddressFetchError('');

      try {
        const addr = await reverseGeocode(position.lat, position.lng);
        if (cancelled || !isMountedRef.current) return;

        if (addr) {
          if (!addressEditedRef.current) {
            setAddress(addr);
            setConfirmed(false);

            emitChange({
              city: selectedCityName,
              address: combineAddress(addr, plaque, unit),
              lat: position.lat,
              lng: position.lng,
            });
          }
        } else {
          setAddressFetchError(
            'آدرسی برای این نقطه پیدا نشد. لطفاً دستی وارد کنید.'
          );
        }
      } catch (err) {
        if (cancelled || !isMountedRef.current) return;
        logDebug('reverse geocode failed:', err);
        setAddressFetchError('خطا در دریافت آدرس خودکار. لطفاً دستی وارد کنید.');
      } finally {
        if (!cancelled && isMountedRef.current) setFetchingAddress(false);
      }
    }, 700);

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [position?.lat, position?.lng, disabled]);

  // ============================================================
  //  🎯 Handlers
  // ============================================================
  const handleCityChange = (e) => {
    const newCityName = e.target.value;
    setSelectedCityName(newCityName);
    setConfirmed(false);
    setLocationError('');
    setAddressFetchError('');
    addressEditedRef.current = false;
    positionSourceRef.current = 'city';

    const cityObj = cities.find((c) => c.name === newCityName);
    if (cityObj) {
      const lat = Number(cityObj.lat);
      const lng = Number(cityObj.lng);
      setPosition({ lat, lng });
      setAddress('');
      setPlaque('');
      setUnit('');
      setTimeout(() => flyTo(lat, lng, 13), 200);

      emitChange({
        city: newCityName,
        address: '',
        lat,
        lng,
      });
    } else {
      setPosition(null);
      setAddress('');
      setPlaque('');
      setUnit('');
      emitChange({ city: '', address: '', lat: null, lng: null });
    }
  };

  const handleMapClick = (lat, lng) => {
    if (disabled) return;
    addressEditedRef.current = false;
    positionSourceRef.current = 'map';
    setPosition({ lat, lng });
    setConfirmed(false);
    setLocationError('');
    setAddressFetchError('');

    emitChange({
      city: selectedCityName,
      address: combineAddress(address, plaque, unit),
      lat,
      lng,
    });
  };

  const handleMarkerDragEnd = (e) => {
    const marker = e.target;
    if (marker && marker.getLatLng) {
      const { lat, lng } = marker.getLatLng();
      addressEditedRef.current = false;
      positionSourceRef.current = 'map';
      setPosition({ lat, lng });
      setConfirmed(false);
      setLocationError('');
      setAddressFetchError('');

      emitChange({
        city: selectedCityName,
        address: combineAddress(address, plaque, unit),
        lat,
        lng,
      });
    }
  };

  const handleAddressChange = (e) => {
    const newAddress = e.target.value;
    setAddress(newAddress);
    addressEditedRef.current = true;
    setAddressFetchError('');
    setConfirmed(false);

    emitChange({
      city: selectedCityName,
      address: combineAddress(newAddress, plaque, unit),
      lat: position?.lat ?? null,
      lng: position?.lng ?? null,
    });
  };

  const handlePlaqueChange = (e) => {
    const newPlaque = e.target.value;
    setPlaque(newPlaque);
    setConfirmed(false);

    emitChange({
      city: selectedCityName,
      address: combineAddress(address, newPlaque, unit),
      lat: position?.lat ?? null,
      lng: position?.lng ?? null,
    });
  };

  const handleUnitChange = (e) => {
    const newUnit = e.target.value;
    setUnit(newUnit);
    setConfirmed(false);

    emitChange({
      city: selectedCityName,
      address: combineAddress(address, plaque, newUnit),
      lat: position?.lat ?? null,
      lng: position?.lng ?? null,
    });
  };

  const handleResetAddressToAuto = async () => {
    if (!position) return;
    addressEditedRef.current = false;
    setFetchingAddress(true);
    setAddressFetchError('');
    try {
      const addr = await reverseGeocode(position.lat, position.lng);
      if (!isMountedRef.current) return;
      if (addr) {
        setAddress(addr);
        setConfirmed(false);

        emitChange({
          city: selectedCityName,
          address: combineAddress(addr, plaque, unit),
          lat: position.lat,
          lng: position.lng,
        });
      } else {
        setAddressFetchError('آدرسی برای این نقطه پیدا نشد.');
      }
    } catch (err) {
      if (isMountedRef.current) {
        setAddressFetchError('خطا در دریافت آدرس.');
      }
    } finally {
      if (isMountedRef.current) setFetchingAddress(false);
    }
  };

  const handleUseMyLocation = () => {
    if (!navigator.geolocation) {
      setLocationError('مرورگر شما از موقعیت‌یابی پشتیبانی نمی‌کند');
      return;
    }
    setLocating(true);
    setLocationError('');
    setAddressFetchError('');

    const options = {
      enableHighAccuracy: true,
      timeout: 15000,
      maximumAge: 0,
    };

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        if (!isMountedRef.current) return;
        const { latitude, longitude, accuracy } = pos.coords;
        addressEditedRef.current = false;
        positionSourceRef.current = 'geo';
        setPosition({ lat: latitude, lng: longitude });
        setConfirmed(false);
        setLocating(false);

        let zoom = 13;
        if (accuracy < 20) zoom = 18;
        else if (accuracy < 50) zoom = 17;
        else if (accuracy < 200) zoom = 15;
        else if (accuracy < 1000) zoom = 13;
        else zoom = 11;

        setTimeout(() => flyTo(latitude, longitude, zoom, 1), 100);

        emitChange({
          city: selectedCityName,
          address: combineAddress(address, plaque, unit),
          lat: latitude,
          lng: longitude,
        });
      },
      (err) => {
        if (!isMountedRef.current) return;
        logDebug('geolocation error:', err);
        setLocating(false);
        if (err.code === err.PERMISSION_DENIED) {
          setLocationError(
            'دسترسی به موقعیت مکانی رد شد. لطفاً دستی روی نقشه کلیک کنید.'
          );
        } else if (err.code === err.POSITION_UNAVAILABLE) {
          setLocationError(
            'سیگنال GPS در دسترس نیست. لطفاً روی نقشه کلیک کنید.'
          );
        } else if (err.code === err.TIMEOUT) {
          setLocationError(
            'دریافت موقعیت طول کشید. لطفاً دستی روی نقشه کلیک کنید.'
          );
        } else {
          setLocationError('دریافت موقعیت ممکن نشد. لطفاً روی نقشه کلیک کنید.');
        }
      },
      options
    );
  };

  const handleConfirm = () => {
    if (!isInside) return;
    if (!position) return;
    if (!address.trim()) {
      setLocationError('لطفاً آدرس دقیق تحویل را وارد کنید');
      return;
    }
    setConfirmed(true);
    setLocationError('');

    const fullAddress = combineAddress(address, plaque, unit);

    saveAddressToList({
      city: selectedCityName,
      address: fullAddress,
      lat: position.lat,
      lng: position.lng,
    });

    emitChange({
      city: selectedCityName,
      address: fullAddress,
      lat: position.lat,
      lng: position.lng,
    });
  };

  const handleReset = () => {
    setPosition(null);
    setAddress('');
    setPlaque('');
    setUnit('');
    setConfirmed(false);
    setLocationError('');
    setAddressFetchError('');
    addressEditedRef.current = false;
    positionSourceRef.current = 'initial';
    setShowPlaqueUnit(false);

    emitChange({
      city: selectedCityName,
      address: '',
      lat: null,
      lng: null,
    });
  };

  const handleSelectSavedAddress = (saved) => {
    setSelectedCityName(saved.city);
    setPosition({ lat: saved.lat, lng: saved.lng });
    const parsed = parseFullAddress(saved.address);
    setAddress(parsed.base);
    setPlaque(parsed.plaque);
    setUnit(parsed.unit);
    if (parsed.plaque || parsed.unit) setShowPlaqueUnit(true);
    setConfirmed(true);
    addressEditedRef.current = true;
    positionSourceRef.current = 'saved';
    setTimeout(() => flyTo(saved.lat, saved.lng, 16), 200);

    emitChange({
      city: saved.city,
      address: saved.address,
      lat: saved.lat,
      lng: saved.lng,
    });
  };

  // ============================================================
  //  ⏳ Loading cities
  // ============================================================
  if (loadingCities) {
    return (
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-2xl p-4 shadow-soft">
        <div className="flex items-center gap-3">
          <div className="inline-block w-5 h-5 border-2 border-brand-500 border-t-transparent rounded-full animate-spin flex-shrink-0" />
          <span className="text-xs text-ink-500 dark:text-cream-400 font-bold">
            در حال دریافت لیست شهرهای مجاز...
          </span>
        </div>
      </div>
    );
  }

  // ============================================================
  //  🏙️ Empty cities — retry button
  // ============================================================
  if (cities.length === 0) {
    return (
      <div className="bg-brand-50 dark:bg-brand-500/15 border-2 border-brand-200 dark:border-brand-500/30 rounded-2xl p-4 text-center">
        <div className="w-10 h-10 mx-auto mb-2" aria-hidden="true">
          <SiteImage
            imageKey="icon_city"
            fallback="🏙️"
            alt=""
            className="w-full h-full object-contain"
          />
        </div>
        <div className="font-display font-black text-brand-800 dark:text-brand-200 text-sm mb-1">
          لیست شهرها در دسترس نیست
        </div>
        <div className="text-[11px] text-brand-700 dark:text-brand-300 leading-relaxed mb-3">
          {citiesError || 'اتصال به سرور برقرار نشد. لطفاً دوباره تلاش کنید.'}
        </div>
        <button
          type="button"
          onClick={retryCities}
          className="inline-flex items-center justify-center gap-1.5 min-h-[40px] px-4 py-2 bg-brand-gradient hover:opacity-95 active:opacity-90 text-white rounded-2xl text-xs font-black transition shadow-brand"
        >
          <span aria-hidden="true">🔄</span>
          <span>تلاش دوباره</span>
        </button>
      </div>
    );
  }

  // ============================================================
  //  🎨 Classes
  // ============================================================
  const inputCls =
    'w-full px-3 py-2.5 min-h-[48px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition font-medium';

  const finalAddress = combineAddress(address, plaque, unit);

  // ============================================================
  //  🎯 رندر نهایی
  // ============================================================
  return (
    <div className="space-y-3">
      {!disabled && (
        <SavedAddressesList
          onSelect={handleSelectSavedAddress}
          disabled={disabled}
        />
      )}

      {/* ===== گام ۱: شهر ===== */}
      <div>
        <label className="flex items-center gap-2 text-xs font-black text-ink-800 dark:text-cream-200 mb-2">
          <StepBadge num="۱" active={!!selectedCityName} />
          <span>شهر تحویل</span>
          <span className="text-brand-500">*</span>
        </label>
        <select
          value={selectedCityName}
          onChange={handleCityChange}
          disabled={disabled}
          className="w-full px-3.5 py-3 min-h-[50px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm font-black bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none cursor-pointer transition disabled:opacity-60"
          aria-label="انتخاب شهر تحویل"
        >
          <option value="">— انتخاب شهر —</option>
          {cities.map((c) => (
            <option key={c.name} value={c.name}>
              🏙️ {c.name}
            </option>
          ))}
        </select>
      </div>

      {/* ===== گام ۲: نقشه ===== */}
      {showMap && (
        <div className="space-y-3 animate-expand-down">
          <label className="flex items-center gap-2 text-xs font-black text-ink-800 dark:text-cream-200 mb-1">
            <StepBadge num="۲" active={!!position} />
            <span>موقعیت دقیق روی نقشه</span>
          </label>

          <div className="bg-brand-50 dark:bg-brand-500/15 border border-brand-200 dark:border-brand-500/30 rounded-2xl p-2.5 sm:p-3 flex items-start gap-2.5">
            <SiteImage
              imageKey="icon_lightbulb"
              fallback="💡"
              alt=""
              className="w-4 h-4 object-contain flex-shrink-0 mt-0.5"
            />
            <div className="flex-1 min-w-0 text-[11px] text-brand-800 dark:text-brand-200 leading-relaxed font-bold">
              برای انتخاب محل: <strong className="font-black">کلیک روی نقشه</strong>،
              <strong className="font-black"> کشیدن مارکر</strong> یا
              <strong className="font-black"> موقعیت فعلی من</strong>.
            </div>
          </div>

          <div className="flex gap-2">
            <button
              type="button"
              onClick={handleUseMyLocation}
              disabled={disabled || locating}
              className="flex-1 min-h-[44px] px-3 py-2.5 bg-brand-gradient hover:opacity-95 active:opacity-90 disabled:bg-paper-200 dark:disabled:bg-ink-700 disabled:text-ink-400 text-white rounded-2xl text-xs font-black transition flex items-center justify-center gap-2 shadow-brand touch-target"
            >
              {locating ? (
                <>
                  <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  <span>در حال یافتن...</span>
                </>
              ) : (
                <>
                  <SiteImage
                    imageKey="icon_target"
                    fallback="🎯"
                    alt=""
                    className="w-4 h-4 object-contain"
                  />
                  <span>موقعیت فعلی من</span>
                </>
              )}
            </button>

            {position && (
              <button
                type="button"
                onClick={handleReset}
                disabled={disabled}
                className="min-h-[44px] px-3 py-2.5 bg-paper-100 dark:bg-ink-700 border border-ink-200 dark:border-dark-600 hover:bg-paper-200 dark:hover:bg-ink-600 active:bg-paper-300 text-ink-700 dark:text-cream-200 rounded-2xl text-xs font-black transition flex items-center justify-center gap-1.5 touch-target"
                title="پاک کردن موقعیت"
              >
                <span aria-hidden="true">↺</span>
                <span className="hidden sm:inline">پاک کردن</span>
              </button>
            )}
          </div>

          {locationError && (
            <div className="bg-rose-50 dark:bg-rose-500/15 border border-rose-200 dark:border-rose-500/30 text-rose-700 dark:text-rose-300 p-3 rounded-2xl text-xs flex items-start gap-2 animate-slide-down break-safe">
              <SiteImage
                imageKey="icon_warning"
                fallback="⚠️"
                alt=""
                className="w-4 h-4 object-contain flex-shrink-0 mt-0.5"
              />
              <span className="leading-relaxed font-bold">{locationError}</span>
            </div>
          )}

          <div
            className="rounded-2xl overflow-hidden border-2 border-ink-200 dark:border-dark-600 shadow-soft h-[240px] sm:h-[320px]"
            role="application"
            aria-label="نقشه انتخاب موقعیت تحویل"
          >
            <MapContainer
              center={
                selectedCity
                  ? [Number(selectedCity.lat), Number(selectedCity.lng)]
                  : TEHRAN_CENTER
              }
              zoom={selectedCity ? DEFAULT_ZOOM_CITY : DEFAULT_ZOOM_COUNTRY}
              scrollWheelZoom={true}
              doubleClickZoom={true}
              dragging={true}
              style={{ height: '100%', width: '100%' }}
            >
              <TileLayer
                attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
                url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
              />
              <MapResizer />
              <MapRefSetter mapRef={mapRef} />
              <MapClickHandler onMapClick={handleMapClick} disabled={disabled} />

              {selectedCity && (
                <Circle
                  center={[Number(selectedCity.lat), Number(selectedCity.lng)]}
                  radius={radiusKm * 1000}
                  pathOptions={{
                    color: BRAND_COLOR,
                    fillColor: BRAND_COLOR,
                    fillOpacity: 0.12,
                    weight: 2,
                    dashArray: '6 4',
                  }}
                />
              )}

              {position && (
                <Marker
                  position={[position.lat, position.lng]}
                  icon={
                    confirmed && isInside
                      ? MARKER_ICON_VALID
                      : !isInside
                      ? MARKER_ICON_INVALID
                      : MARKER_ICON_ACTIVE
                  }
                  draggable={!disabled}
                  eventHandlers={{ dragend: handleMarkerDragEnd }}
                />
              )}
            </MapContainer>
          </div>

          {position ? (
            <div
              className={`rounded-2xl border-2 p-3 flex items-start gap-2.5 transition ${
                isInside
                  ? 'bg-accent-50 dark:bg-accent-500/15 border-accent-200 dark:border-accent-500/30'
                  : 'bg-rose-50 dark:bg-rose-500/15 border-rose-200 dark:border-rose-500/30'
              }`}
            >
              <div
                className={`w-9 h-9 rounded-full flex items-center justify-center p-2 flex-shrink-0 ${
                  isInside
                    ? 'bg-accent-100 dark:bg-accent-500/25 text-accent-700 dark:text-accent-300'
                    : 'bg-rose-100 dark:bg-rose-500/25 text-rose-700 dark:text-rose-300'
                }`}
                aria-hidden="true"
              >
                {isInside ? (
                  <SiteImage
                    imageKey="icon_check"
                    fallback="✅"
                    alt=""
                    className="w-full h-full object-contain"
                  />
                ) : (
                  <SiteImage
                    imageKey="icon_error"
                    fallback="❌"
                    alt=""
                    className="w-full h-full object-contain"
                  />
                )}
              </div>
              <div className="flex-1 min-w-0">
                <div
                  className={`font-display font-black text-xs ${
                    isInside
                      ? 'text-accent-800 dark:text-accent-200'
                      : 'text-rose-800 dark:text-rose-200'
                  }`}
                >
                  {isInside
                    ? `داخل محدوده ${selectedCity?.name}`
                    : `خارج از محدوده ${selectedCity?.name}`}
                </div>
                {!isInside && (
                  <div className="text-[11px] text-rose-700 dark:text-rose-300 mt-1 leading-relaxed font-bold">
                    متأسفانه به این نقطه ارسال نداریم. لطفاً محل دیگری داخل دایره انتخاب کنید.
                  </div>
                )}
              </div>
            </div>
          ) : (
            <div className="rounded-2xl border-2 border-dashed border-ink-200 dark:border-dark-600 bg-paper-100/50 dark:bg-ink-900/30 p-4 text-center">
              <div className="text-2xl mb-1 opacity-60" aria-hidden="true">👆</div>
              <div className="text-xs text-ink-500 dark:text-cream-400 font-bold">
                برای مشخص کردن محل دقیق، روی نقشه کلیک کنید یا «موقعیت فعلی من» را بزنید
              </div>
            </div>
          )}

          {/* ===== گام ۳: آدرس دقیق ===== */}
          {position && (
            <div className="animate-expand-down space-y-3 pt-2 border-t border-ink-200 dark:border-dark-700">
              <label className="flex items-center gap-2 text-xs font-black text-ink-800 dark:text-cream-200 pt-2">
                <StepBadge num="۳" active={!!address} />
                <span>آدرس دقیق تحویل</span>
                <span className="text-brand-500">*</span>
              </label>

              <div>
                <div className="flex items-center justify-between gap-2 mb-1.5 flex-wrap">
                  <span className="text-[10px] text-ink-500 dark:text-cream-400 font-bold">
                    آدرس خودکار از روی نقشه گرفته شده — می‌تونی ویرایش کنی
                  </span>

                  <div className="flex items-center gap-1.5">
                    {fetchingAddress && (
                      <span className="inline-flex items-center gap-1 text-[10px] text-brand-600 dark:text-brand-400 font-black">
                        <span className="inline-block w-3 h-3 border-2 border-brand-500 border-t-transparent rounded-full animate-spin" />
                        <span>دریافت خودکار...</span>
                      </span>
                    )}
                    {!fetchingAddress && !addressEditedRef.current && address && (
                      <span className="inline-flex items-center gap-1 text-[10px] text-accent-600 dark:text-accent-400 font-black">
                        <SiteImage
                          imageKey="icon_check"
                          fallback="✅"
                          alt=""
                          className="w-3 h-3 object-contain"
                        />
                        <span>خودکار</span>
                      </span>
                    )}
                    {addressEditedRef.current && (
                      <span className="inline-flex items-center gap-1 text-[10px] text-brand-600 dark:text-brand-400 font-black">
                        <SiteImage
                          imageKey="icon_edit"
                          fallback="✏️"
                          alt=""
                          className="w-3 h-3 object-contain"
                        />
                        <span>ویرایش‌شده</span>
                      </span>
                    )}
                  </div>
                </div>

                <textarea
                  value={address}
                  onChange={handleAddressChange}
                  disabled={disabled}
                  rows="2"
                  maxLength={MAX_ADDRESS_LEN}
                  placeholder={
                    fetchingAddress
                      ? 'در حال دریافت آدرس از روی نقشه...'
                      : 'مثال: بابل، بلوار جانبازان، توحید ۳۲'
                  }
                  className="w-full px-3 py-3 min-h-[72px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none resize-none transition leading-relaxed"
                  aria-label="آدرس دقیق تحویل"
                />

                <div className="flex items-center justify-between mt-1.5 gap-2 flex-wrap">
                  <div className="text-[10px] text-ink-500 dark:text-cream-400 leading-relaxed font-bold flex items-center gap-1">
                    <SiteImage
                      imageKey="icon_lightbulb"
                      fallback="💡"
                      alt=""
                      className="w-3 h-3 object-contain flex-shrink-0"
                    />
                    <span>اگر آدرس اشتباه یا ناقص بود، خودتان ویرایش کنید</span>
                  </div>
                  <div className="text-[10px] text-ink-400 dark:text-cream-500 font-num flex-shrink-0">
                    {toFa(address.length)} / {toFa(MAX_ADDRESS_LEN)}
                  </div>
                </div>

                {addressEditedRef.current && position && (
                  <button
                    type="button"
                    onClick={handleResetAddressToAuto}
                    disabled={disabled || fetchingAddress}
                    className="mt-2 inline-flex items-center gap-1.5 min-h-[36px] px-3 py-1.5 bg-brand-50 dark:bg-brand-500/15 hover:bg-brand-100 dark:hover:bg-brand-500/25 active:bg-brand-200 text-brand-700 dark:text-brand-300 border border-brand-200 dark:border-brand-500/30 rounded-2xl text-[11px] font-black transition touch-target disabled:opacity-50"
                    title="دریافت مجدد آدرس از روی نقشه"
                  >
                    <span aria-hidden="true">🔄</span>
                    <span>بازنشانی به آدرس خودکار</span>
                  </button>
                )}

                {addressFetchError && (
                  <div className="mt-2 bg-brand-50 dark:bg-brand-500/15 border border-brand-200 dark:border-brand-500/30 text-brand-700 dark:text-brand-300 p-2.5 rounded-2xl text-[11px] flex items-start gap-2 break-safe">
                    <SiteImage
                      imageKey="icon_info"
                      fallback="ℹ️"
                      alt=""
                      className="w-4 h-4 object-contain flex-shrink-0 mt-0.5"
                    />
                    <span className="leading-relaxed font-bold">{addressFetchError}</span>
                  </div>
                )}
              </div>

              {/* پلاک و واحد */}
              <div className="bg-paper-100/50 dark:bg-ink-900/40 border-2 border-ink-200 dark:border-dark-600 rounded-2xl overflow-hidden">
                <button
                  type="button"
                  onClick={() => setShowPlaqueUnit(!showPlaqueUnit)}
                  className="w-full flex items-center justify-between gap-2 p-3 min-h-[44px] text-right hover:bg-paper-100 dark:hover:bg-ink-800/50 active:bg-paper-200 transition touch-target"
                  aria-expanded={showPlaqueUnit}
                >
                  <div className="flex items-center gap-2 min-w-0">
                    <span className="text-base flex-shrink-0" aria-hidden="true">🏢</span>
                    <span className="text-xs font-black text-ink-800 dark:text-cream-200">
                      پلاک و واحد
                    </span>
                    <span className="text-[10px] text-ink-400 dark:text-cream-500 font-bold">
                      (اختیاری)
                    </span>
                    {(plaque || unit) && (
                      <span className="text-[10px] bg-accent-100 dark:bg-accent-500/20 text-accent-700 dark:text-accent-300 px-2 py-0.5 rounded-full font-black">
                        {plaque && `پلاک ${plaque}`}
                        {plaque && unit && ' · '}
                        {unit && `واحد ${unit}`}
                      </span>
                    )}
                  </div>
                  <span
                    className={`flex-shrink-0 w-7 h-7 rounded-2xl flex items-center justify-center text-[10px] font-black transition-all ${
                      showPlaqueUnit
                        ? 'rotate-90 bg-brand-gradient text-white shadow-brand'
                        : 'bg-paper-100 dark:bg-ink-700 text-ink-500 dark:text-cream-400'
                    }`}
                    aria-hidden="true"
                  >
                    ◀
                  </span>
                </button>

                {showPlaqueUnit && (
                  <div className="border-t border-ink-200 dark:border-dark-700 p-3 space-y-2 animate-expand-down">
                    <div className="grid grid-cols-2 gap-2">
                      <div>
                        <label className="flex items-center gap-1 text-[10px] font-black text-ink-500 dark:text-cream-400 mb-1">
                          <SiteImage
                            imageKey="icon_house"
                            fallback="🏠"
                            alt=""
                            className="w-3 h-3 object-contain"
                          />
                          <span>پلاک</span>
                        </label>
                        <input
                          type="text"
                          value={plaque}
                          onChange={handlePlaqueChange}
                          disabled={disabled}
                          placeholder="مثال: ۱۵"
                          maxLength={MAX_PLAQUE_LEN}
                          className={inputCls}
                          aria-label="پلاک"
                        />
                      </div>
                      <div>
                        <label className="block text-[10px] font-black text-ink-500 dark:text-cream-400 mb-1">
                          🚪 واحد
                        </label>
                        <input
                          type="text"
                          value={unit}
                          onChange={handleUnitChange}
                          disabled={disabled}
                          placeholder="مثال: ۳"
                          maxLength={MAX_UNIT_LEN}
                          className={inputCls}
                          aria-label="واحد"
                        />
                      </div>
                    </div>
                  </div>
                )}
              </div>

              {/* پیش‌نمایش آدرس نهایی */}
              {finalAddress && (
                <div className="bg-accent-50 dark:bg-accent-500/15 border border-accent-200 dark:border-accent-500/30 rounded-2xl p-3">
                  <div className="text-[10px] text-accent-700 dark:text-accent-300 mb-1 font-black flex items-center gap-1.5">
                    <SiteImage
                      imageKey="icon_orders"
                      fallback="📦"
                      alt=""
                      className="w-3.5 h-3.5 object-contain"
                    />
                    <span>آدرس نهایی برای پیک:</span>
                  </div>
                  <div className="text-xs font-black text-accent-800 dark:text-accent-200 break-safe leading-relaxed">
                    {finalAddress}
                  </div>
                </div>
              )}

              {/* دکمه تأیید */}
              <button
                type="button"
                onClick={handleConfirm}
                disabled={
                  disabled || !isInside || !address.trim() || confirmed || fetchingAddress
                }
                className={`w-full min-h-[48px] px-4 py-3 rounded-2xl text-sm font-black transition flex items-center justify-center gap-2 shadow-soft touch-target ${
                  confirmed
                    ? 'bg-accent-500 text-white cursor-default'
                    : !isInside || !address.trim() || fetchingAddress
                    ? 'bg-paper-200 dark:bg-ink-700 text-ink-400 dark:text-cream-500 cursor-not-allowed'
                    : 'bg-brand-gradient hover:opacity-95 active:opacity-90 text-white shadow-brand hover:shadow-brand-lg'
                }`}
              >
                {confirmed ? (
                  <>
                    <SiteImage
                      imageKey="icon_check"
                      fallback="✓"
                      alt=""
                      className="w-4 h-4 object-contain"
                    />
                    <span>موقعیت تأیید شد</span>
                  </>
                ) : fetchingAddress ? (
                  <>
                    <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                    <span>در حال دریافت آدرس...</span>
                  </>
                ) : (
                  <>
                    <SiteImage
                      imageKey="icon_check"
                      fallback="📌"
                      alt=""
                      className="w-4 h-4 object-contain"
                    />
                    <span>تأیید موقعیت و ادامه</span>
                  </>
                )}
              </button>
            </div>
          )}
        </div>
      )}

      {/* inline citiesError با retry */}
      {citiesError && cities.length > 0 && (
        <div className="bg-rose-50 dark:bg-rose-500/15 border border-rose-200 dark:border-rose-500/30 text-rose-700 dark:text-rose-300 p-3 rounded-2xl text-xs flex items-start gap-2">
          <SiteImage
            imageKey="icon_warning"
            fallback="⚠️"
            alt=""
            className="w-4 h-4 object-contain flex-shrink-0 mt-0.5"
          />
          <span className="font-bold">{citiesError}</span>
        </div>
      )}
    </div>
  );
}

// ============================================================
//  ✅ Helper: اعتبارسنجی از سمت والد
// ============================================================
export function isDeliveryValid(delivery) {
  if (!delivery) return false;
  const { city, address, lat, lng } = delivery;
  if (!city || !address || lat == null || lng == null) return false;
  if (typeof address !== 'string' || address.trim().length < 3) return false;
  if (!Number.isFinite(Number(lat)) || !Number.isFinite(Number(lng))) return false;
  if (Number(lat) < -90 || Number(lat) > 90) return false;
  if (Number(lng) < -180 || Number(lng) > 180) return false;
  return true;
}